    b.append(f'<rect x="440" y="964" width="320" height="3" fill="{ori_fill}" opacity=".7"/>')
    b.append(txt('ORIHUELA',600,1012,30,ori_fill,16,fam='Montserrat',weight=700,extra=f'filter="url(#{filt})"'))
